def extract_json_dict(text):


    """


    Extract the first JSON dictionary (object) from a string using regex.


    """


    # This regex matches balanced curly braces for a JSON object


    methods = [


        # Method 1: JSON in code blocks


        lambda t: re.search(r'```(?:json)?\s*(\{.*?\})\s*```', t, re.DOTALL),


        # Method 2: Balanced braces


        # Method 3: Simple pattern


        lambda t: re.search(r'\{(?:[^{}]|{[^{}]*})*\}', t, re.DOTALL)


    ]





    for method in methods:


        try:


            result = method(text)


            if result:


                if hasattr(result, 'group'):  # regex match object


                    json_str = result.group(1) if result.groups() else result.group()


                else:  # already parsed JSON


                    return result


                return json.loads(json_str)


        except (json.JSONDecodeError, AttributeError):


            continue


    return None





